css:
.toggle-wrapper {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  column-gap: 0.25em;
}

.toggle-checkbox {
  -webkit-appearance: none;
  appearance: none;
  position: absolute;
  z-index: 1;
  border-radius: 3.125em;
  width: 6.5em; /* Increase width */
  height: 2.5em; /* Increase height */
  opacity: 0;
  cursor: pointer;
}

.toggle-container {
  position: relative;
  border-radius: 3.125em;
  width: 6.5em; /* Increase width */
  height: 2.5em; /* Increase height */
  background-image: repeating-conic-gradient(
    #0b66a0 0% 20%,
    #1093a8 0% 40%
  ); /* Increase line width */
  background-size: 0.25em 0.25em; /* Increase size of the lines */
  box-shadow:
    inset 0 0.125em 0.25em rgba(#000926, 0.6),
    inset -1.5em 0 0.0625em rgba(#000926, 0.5),
    inset 0.5em 0 0.5em rgba(#000926, 0.5),
    0 1px 1px rgb(255 255 255 / 0.4);
}

.toggle-button {
  display: flex;
  justify-content: center;
  align-items: center;
  position: absolute;
  top: 0.0625em;
  left: 0.0625em;
  border-radius: inherit;
  width: 3.2em; /* Increase width */
  height: calc(100% - 0.125em);
  background-image: linear-gradient(to right, #86e2fa, #125e79);
  box-shadow: 0 0.125em 0.25em rgb(0 0 0 / 0.6);
  transition: left 0.4s;

  .toggle-checkbox:checked ~ .toggle-container > & {
    left: 3.4em; /* Increase the position of the thumb */
  }

  &::before {
    content: "";
    position: absolute;
    top: inherit;
    border-radius: inherit;
    width: calc(100% - 0.375em);
    height: inherit;
    background-image: linear-gradient(to right, #0f73a8, #57cfe2, #b3f0ff);
  }

  &::after {
    content: "";
    position: absolute;
    width: 0.75em; /* Increase line width */
    height: 40%; /* Increase height of the line */
    background-image: repeating-linear-gradient(
      to right,
      #d2f2f6 0 0.125em,
      #4ea0ae 0.125em 0.25em,
      transparent 0.25em 0.375em
    );
  }
}
